{"function": "() => {
    const articles = [];
    const articleElements = document.querySelectorAll('article');
    articleElements.forEach(article => {
        const titleElem = article.querySelector('h3 a');
        const title = titleElem ? titleElem.textContent.trim() : '';
        const link = titleElem ? titleElem.href : '';
        const authorsList = article.querySelector('ul');
        let authors = [];
        if (authorsList) {
            authors = Array.from(authorsList.children).map(li => li.textContent.trim()).filter(text => text);
        }
        const meta = article.querySelectorAll('span');
        let type = '';
        let access = '';
        let date = '';
        // Find the meta spans
        for (let span of meta) {
            const text = span.textContent.trim();
            if (text.includes('Conference Proceeding')) type = text;
            if (text.includes('Open Access')) access = text;
            if (text.match(/\d{1,2} \w+ \d{4}/)) date = text;
        }
        articles.push({
            title,
            link,
            authors,
            type,
            access,
            date
        });
    });
    return articles;
}"}

