{"function": "() => {
    const articles = [];
    const articleElements = document.querySelectorAll('article');
    articleElements.forEach(article => {
        const titleLink = article.querySelector('h3 a');
        const title = titleLink ? titleLink.textContent.trim() : '';
        const link = titleLink ? titleLink.href : '';

        // Authors list (may be truncated)
        const authorsList = article.querySelector('ul');
        let authors = [];
        if (authorsList) {
            authors = Array.from(authorsList.children).map(li => {
                let text = li.textContent.trim();
                // Remove leading/trailing commas
                text = text.replace(/^,\s*/, '').replace(/\s*,$/, '');
                return text;
            }).filter(text => text);
        }

        // Meta information
        const metaSpans = article.querySelectorAll('span');
        let type = '';
        let access = '';
        for (let span of metaSpans) {
            const text = span.textContent.trim();
            if (text === 'Conference Proceeding') type = text;
            if (text === 'Open Access') access = text;
        }

        const timeElem = article.querySelector('time');
        const date = timeElem ? timeElem.textContent.trim() : '';

        articles.push({
            title,
            link,
            authors,
            type,
            access,
            date
        });
    });
    return articles;
}"}

